import React from 'react';
import { Box, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';

const Logo = ({ variant = 'full', size = 'medium', ...props }) => {
  const theme = useTheme();
  
  const sizes = {
    small: { height: 32, fontSize: '1.2rem' },
    medium: { height: 40, fontSize: '1.5rem' },
    large: { height: 48, fontSize: '1.8rem' },
  };

  const currentSize = sizes[size] || sizes.medium;

  if (variant === 'icon') {
    return (
      <Box
        sx={{
          width: currentSize.height,
          height: currentSize.height,
          background: 'linear-gradient(135deg, #1976d2 30%, #42a5f5 90%)',
          borderRadius: '8px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          fontWeight: 'bold',
          fontSize: currentSize.fontSize,
          ...props.sx,
        }}
        {...props}
      >
        के
      </Box>
    );
  }

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        gap: 1,
        ...props.sx,
      }}
      {...props}
    >
      <Box
        sx={{
          width: currentSize.height,
          height: currentSize.height,
          background: 'linear-gradient(135deg, #1976d2 30%, #42a5f5 90%)',
          borderRadius: '8px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          fontWeight: 'bold',
          fontSize: currentSize.fontSize,
        }}
      >
        के
      </Box>
      <Box>
        <Typography
          variant="h6"
          sx={{
            fontSize: currentSize.fontSize,
            fontWeight: 600,
            color: theme.palette.primary.main,
            lineHeight: 1,
          }}
        >
          KaamHeru
        </Typography>
        <Typography
          variant="caption"
          sx={{
            fontSize: '0.7rem',
            color: theme.palette.text.secondary,
            lineHeight: 1,
            display: 'block',
          }}
        >
          कामहेरू
        </Typography>
      </Box>
    </Box>
  );
};

export default Logo;
