import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Grid,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Alert,
  Divider,
} from '@mui/material';
import { useParams } from 'react-router-dom';
import api from '../../services/api';

const statusColors = {
  planning: 'warning',
  in_progress: 'info',
  completed: 'success',
  delayed: 'error',
  cancelled: 'default',
};

const ProjectDetailPublic = () => {
  const { id } = useParams();
  const [project, setProject] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchProject();
  }, [id]);

  const fetchProject = async () => {
    try {
      const res = await api.get(`/projects/${id}`);
      setProject(res.data.data?.project || null);
    } catch (err) {
      setError('Failed to load project details');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Paper sx={{ p: 3, textAlign: 'center' }}>
        <CircularProgress />
        <Typography variant="body2" sx={{ mt: 2 }}>Loading project details...</Typography>
      </Paper>
    );
  }

  if (error || !project) {
    return (
      <Paper sx={{ p: 3 }}>
        <Alert severity="error">
          {error || 'Project not found'}
        </Alert>
      </Paper>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        {project.title}
      </Typography>

      <Grid container spacing={3}>
        <Grid item xs={12} md={8}>
          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              Project Description
            </Typography>
            <Typography variant="body1" paragraph>
              {project.description}
            </Typography>

            {project.tags && project.tags.length > 0 && (
              <Box sx={{ mt: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Tags
                </Typography>
                <Box>
                  {project.tags.map((tag, index) => (
                    <Chip
                      key={index}
                      label={tag}
                      variant="outlined"
                      size="small"
                      sx={{ mr: 1, mb: 1 }}
                    />
                  ))}
                </Box>
              </Box>
            )}
          </Paper>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              Project Timeline
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Typography variant="body2" color="text.secondary">
                  Start Date
                </Typography>
                <Typography variant="body1">
                  {new Date(project.startDate).toLocaleDateString()}
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="body2" color="text.secondary">
                  End Date
                </Typography>
                <Typography variant="body1">
                  {new Date(project.endDate).toLocaleDateString()}
                </Typography>
              </Grid>
            </Grid>
          </Paper>
        </Grid>

        <Grid item xs={12} md={4}>
          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              Project Status
            </Typography>
            <Chip
              label={project.status?.replace('_', ' ')}
              color={statusColors[project.status] || 'default'}
              sx={{ mb: 2 }}
            />
            <Typography variant="body2" color="text.secondary">
              Current phase: {project.status?.replace('_', ' ') || 'Not specified'}
            </Typography>
          </Paper>

          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              Location Details
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Municipality
            </Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              {project.municipality}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Specific Location
            </Typography>
            <Typography variant="body1">
              {project.location}
            </Typography>
          </Paper>

          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              Budget Information
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Total Budget
            </Typography>
            <Typography variant="h5" color="primary">
              NPR {project.budget?.toLocaleString()}
            </Typography>
          </Paper>

          {project.assignedContractor && (
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                Assigned Contractor
              </Typography>
              <Typography variant="body1">
                {project.assignedContractor.fullName}
              </Typography>
              {project.assignedContractor.contractorDetails?.companyName && (
                <Typography variant="body2" color="text.secondary">
                  {project.assignedContractor.contractorDetails.companyName}
                </Typography>
              )}
              {project.assignedContractor.contractorDetails?.contractorId && (
                <Chip
                  label={project.assignedContractor.contractorDetails.contractorId}
                  variant="outlined"
                  size="small"
                  sx={{ mt: 1 }}
                />
              )}
            </Paper>
          )}
        </Grid>
      </Grid>
    </Box>
  );
};

export default ProjectDetailPublic;
